DELETE FROM ar_ling_lexicon_block_rekey WHERE root_norm_canonical NOT IN (SELECT lookup_norm FROM ar_ling_root_lexicon_key) OR root_norm_canonical = root_norm;
DROP VIEW IF EXISTS ar_ling_root_lexicon_block_v;
CREATE VIEW ar_ling_root_lexicon_block_v AS
SELECT k.root_norm AS root_norm, k.lookup_norm AS found_under, k.key_rank AS key_rank, b.id AS block_id, b.source_slug AS source_slug, b.root_entry_id AS root_entry_id, b.block_type AS block_type, b.block_seq AS block_seq, b.depth AS depth, b.lang AS lang, b.title_ar AS title_ar, b.title_en AS title_en, b.text_plain AS text_plain, b.translation_en AS translation_en, b.printed_page AS printed_page
  FROM ar_ling_root_lexicon_key k JOIN ar_ling_lexicon_block b ON b.root_norm = k.lookup_norm
 WHERE NOT EXISTS (SELECT 1 FROM ar_ling_lexicon_block_rekey r WHERE r.block_id = b.id)
UNION ALL
SELECT k.root_norm AS root_norm, k.lookup_norm AS found_under, k.key_rank AS key_rank, b.id AS block_id, b.source_slug AS source_slug, b.root_entry_id AS root_entry_id, b.block_type AS block_type, b.block_seq AS block_seq, b.depth AS depth, b.lang AS lang, b.title_ar AS title_ar, b.title_en AS title_en, b.text_plain AS text_plain, b.translation_en AS translation_en, b.printed_page AS printed_page
  FROM ar_ling_root_lexicon_key k JOIN ar_ling_lexicon_block_rekey r ON r.root_norm_canonical = k.lookup_norm
  JOIN ar_ling_lexicon_block b ON b.id = r.block_id;
DROP VIEW IF EXISTS ar_ling_root_lexicon_entry_v;
CREATE VIEW ar_ling_root_lexicon_entry_v AS
SELECT k.root_norm AS root_norm, k.lookup_norm AS found_under, k.key_rank AS key_rank, e.id AS entry_id, e.source_slug AS source_slug, e.source_id AS source_id, e.root_id AS root_id, e.root_text AS root_text, e.raw_text AS raw_text, e.entry_text_ar AS entry_text_ar, e.entry_text_en AS entry_text_en, e.translation_en AS translation_en, e.translation_ur AS translation_ur, e.entry_gloss_json AS entry_gloss_json, e.family_json AS family_json, e.page_start AS page_start, e.page_end AS page_end, e.volume_no AS volume_no, e.status AS status
  FROM ar_ling_root_lexicon_key k JOIN ar_ling_lexicon_entry e ON e.root_norm = k.lookup_norm
 WHERE e.root_norm_canonical IS NULL OR e.root_norm_canonical = e.root_norm
    OR NOT EXISTS (SELECT 1 FROM ar_ling_root_lexicon_key k2 WHERE k2.lookup_norm = e.root_norm_canonical)
UNION ALL
SELECT k.root_norm AS root_norm, k.lookup_norm AS found_under, k.key_rank AS key_rank, e.id AS entry_id, e.source_slug AS source_slug, e.source_id AS source_id, e.root_id AS root_id, e.root_text AS root_text, e.raw_text AS raw_text, e.entry_text_ar AS entry_text_ar, e.entry_text_en AS entry_text_en, e.translation_en AS translation_en, e.translation_ur AS translation_ur, e.entry_gloss_json AS entry_gloss_json, e.family_json AS family_json, e.page_start AS page_start, e.page_end AS page_end, e.volume_no AS volume_no, e.status AS status
  FROM ar_ling_root_lexicon_key k JOIN ar_ling_lexicon_entry e ON e.root_norm_canonical = k.lookup_norm
 WHERE e.root_norm_canonical <> e.root_norm;
